Here is the commit message:
USB: OHCI: Fix race between ED unlink and URB submission

This patch fixes a bug introduced by commit 977dcfdc6031 ("USB: OHCI:
don't lose track of EDs when a controller dies").  The commit changed
ed_state from ED_UNLINK to ED_IDLE too early, before finish_urb() had
been called.  The user-visible consequence is that the driver
occasionally crashes or locks up when an URB is submitted while
another URB for the same endpoint is being unlinked.

This patch moves the ED state change later, to the right place.  The
drawback is that now we may unnecessarily execute some instructions
multiple times when a controller dies.  Since controllers dying is an
exceptional occurrence, a little wasted time won't matter.

Signed-off-by: Alan Stern <stern@rowland.harvard.edu>
Reported-by: Heiko Przybyl <lil_tux@web.de>
Tested-by: Heiko Przybyl <lil_tux@web.de>
Fixes: 977dcfdc60311e7aa571cabf6f39c36dde13339e
CC: <stable@vger.kernel.org>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by changing the endpoint descriptor (ED) state from `ED_UNLINK` to `ED_IDLE` too early, before the `finish_urb()` function had completed its operations. This premature state change allowed for a race condition where an URB could be submitted while another URB for the same endpoint was being unlinked, leading to crashes or deadlocks in the driver.

Here is the patch:
 /* there are some urbs/eds to unlink; called in_irq(), with HCD locked */
 static void finish_unlinks(struct ohci_hcd *ohci)
 {
 	unsigned	tick = ohci_frame_no(ohci);
 	struct ed	*ed, **last;

 rescan_all:
 	for (last = &ohci->ed_rm_list, ed = *last; ed != NULL; ed = *last) {
 		struct list_head	*entry, *tmp;
 		int			completed, modified;
 		__hc32			*prev;

-		/* Is this ED already invisible to the hardware? */
-		if (ed->state == ED_IDLE)
-			goto ed_idle;
-
 		/* only take off EDs that the HC isn't using, accounting for
 		 * frame counter wraps and EDs with partially retired TDs
 		 */
 		if (likely(ohci->rh_state == OHCI_RH_RUNNING) &&
 				tick_before(tick, ed->tick)) {
 skip_ed:
 			last = &ed->ed_next;
 			continue;
 		}
 		if (!list_empty(&ed->td_list)) {
 			struct td	*td;
 			u32		head;

 			td = list_first_entry(&ed->td_list, struct td, td_list);

 			/* INTR_WDH may need to clean up first */
 			head = hc32_to_cpu(ohci, ed->hwHeadP) & TD_MASK;
 			if (td->td_dma != head &&
 					ohci->rh_state == OHCI_RH_RUNNING)
 				goto skip_ed;

 			/* Don't mess up anything already on the done list */
 			if (td->next_dl_td)
 				goto skip_ed;
 		}

 		/* ED's now officially unlinked, hc doesn't see */
-		ed->state = ED_IDLE;
 		ed->hwHeadP &= ~cpu_to_hc32(ohci, ED_H);
 		ed->hwNextED = 0;
 		wmb();
 		ed->hwINFO &= ~cpu_to_hc32(ohci, ED_SKIP | ED_DEQUEUE);
-ed_idle:

 		/* reentrancy:  if we drop the schedule lock, someone might
 		 * have modified this list.  normally it's just prepending
 		 * entries (which we'd ignore), but paranoia won't hurt.
 		 */
 		modified = 0;

 		/* unlink urbs as requested, but rescan the list after
 		 * we call a completion since it might have unlinked
 		 * another (earlier) urb
 		 *
 		 * When we get here, the HC doesn't see this ed.  But it
 		 * must not be rescheduled until all completed URBs have
 		 * been given back to the driver.
 		 */
 rescan_this:
 		completed = 0;
 		prev = &ed->hwHeadP;
 		list_for_each_safe (entry, tmp, &ed->td_list) {
 			struct td	*td;
 			struct urb	*urb;
 			urb_priv_t	*urb_priv;
 			__hc32		savebits;
 			u32		tdINFO;

 			td = list_entry (entry, struct td, td_list);
 			urb = td->urb;
 			urb_priv = td->urb->hcpriv;

 			if (!urb->unlinked) {
 				prev = &td->hwNextTD;
 				continue;
 			}

 			/* patch pointer hc uses */
 			savebits = *prev & ~cpu_to_hc32 (ohci, TD_MASK);
 			*prev = td->hwNextTD | savebits;

 			/* If this was unlinked, the TD may not have been
 			 * retired ... so manually save the data toggle.
 			 * The controller ignores the value we save for
 			 * control and ISO endpoints.
 			 */
 			tdINFO = hc32_to_cpup(ohci, &td->hwINFO);
 			if ((tdINFO & TD_T) == TD_T_DATA0)
 				ed->hwHeadP &= ~cpu_to_hc32(ohci, ED_C);
 			else if ((tdINFO & TD_T) == TD_T_DATA1)
 				ed->hwHeadP |= cpu_to_hc32(ohci, ED_C);

 			/* HC may have partly processed this TD */
 			td_done (ohci, urb, td);
 			urb_priv->td_cnt++;

 			/* if URB is done, clean up */
 			if (urb_priv->td_cnt >= urb_priv->length) {
 				modified = completed = 1;
 				finish_urb(ohci, urb, 0);
 			}
 		}
 		if (completed && !list_empty (&ed->td_list))
 			goto rescan_this;

 		/*
 		 * If no TDs are queued, take ED off the ed_rm_list.
 		 * Otherwise, if the HC is running, reschedule.
 		 * If not, leave it on the list for further dequeues.
 		 */
 		if (list_empty(&ed->td_list)) {
 			*last = ed->ed_next;
 			ed->ed_next = NULL;
+			ed->state = ED_IDLE;
 			list_del(&ed->in_use_list);
 		} else if (ohci->rh_state == OHCI_RH_RUNNING) {
 			*last = ed->ed_next;
 			ed->ed_next = NULL;
 			ed_schedule(ohci, ed);
 		} else {
 			last = &ed->ed_next;
 		}

 		if (modified)
 			goto rescan_all;
 	}

 	/* maybe reenable control and bulk lists */
 	if (ohci->rh_state == OHCI_RH_RUNNING && !ohci->ed_rm_list) {
 		u32	command = 0, control = 0;

 		if (ohci->ed_controltail) {
 			command |= OHCI_CLF;
 			if (quirk_zfmicro(ohci))
 				mdelay(1);
 			if (!(ohci->hc_control & OHCI_CTRL_CLE)) {
 				control |= OHCI_CTRL_CLE;
 				ohci_writel (ohci, 0,
 					&ohci->regs->ed_controlcurrent);
 			}
 		}
 		if (ohci->ed_bulktail) {
 			command |= OHCI_BLF;
 			if (quirk_zfmicro(ohci))
 				mdelay(1);
 			if (!(ohci->hc_control & OHCI_CTRL_BLE)) {
 				control |= OHCI_CTRL_BLE;
 				ohci_writel (ohci, 0,
 					&ohci->regs->ed_bulkcurrent);
 			}
 		}

 		/* CLE/BLE to enable, CLF/BLF to (maybe) kickstart */
 		if (control) {
 			ohci->hc_control |= control;
 			if (quirk_zfmicro(ohci))
 				mdelay(1);
 			ohci_writel (ohci, ohci->hc_control,
 					&ohci->regs->control);
 		}
 		if (command) {
 			if (quirk_zfmicro(ohci))
 				mdelay(1);
 			ohci_writel (ohci, command, &ohci->regs->cmdstatus);
 		}
 	}
 }



